#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

static uint32_t rotl32(uint32_t x, unsigned n) {
    n &= 31;
    return (x << n) | (x >> ((32 - n) & 31));
}

static uint32_t rotr32(uint32_t x, unsigned n) {
    n &= 31;
    return (x >> n) | (x << ((32 - n) & 31));
}

int main(void) {
    char command[8];
    uint32_t x;
    unsigned n;
    while (scanf("%7s %" SCNu32 " %u", command, &x, &n) == 3) {
        uint32_t result = strcmp(command, "rol") == 0 ? rotl32(x, n) : rotr32(x, n);
        printf("%08" PRIX32 "\n", result);
    }
    return 0;
}

additionalExercises.description:
В графике цвет часто хранят в 24 битах (`#RRGGBB`, по 8 бит на канал), а в экранах микроконтроллеров — в 16 битах формата RGB565: 5 бит красного (биты 11–15), 6 бит зелёного (5–10) и 5 бит синего (0–4).

Команды до конца ввода:
- `pack R G B` — напечатать `#RRGGBB 565:0xHHHH`: цвет в 24-битной записи и в RGB565, где каждый канал — старшие биты 8-битного значения (`R >> 3`, `G >> 2`, `B >> 3`);
- `unpack #RRGGBB` — напечатать три числа `R G B`;
- `expand 0xHHHH` — перевести RGB565 обратно в 8 бит на канал и напечатать `R G B`. Расширение повторяет старшие биты в младших: для 5-битного `r` — `(r << 3) | (r >> 2)`, для 6-битного `g` — `(g << 2) | (g >> 4)`.

Шестнадцатеричные цифры печатайте заглавными.

