#include <stdio.h>
#include <string.h>

int main(void) {
    char command[16];
    while (scanf("%15s", command) == 1) {
        if (strcmp(command, "pack") == 0) {
            unsigned r, g, b;
            if (scanf("%u %u %u", &r, &g, &b) != 3) {
                break;
            }
            unsigned rgb = r << 16 | g << 8 | b;
            unsigned rgb565 = (r >> 3) << 11 | (g >> 2) << 5 | (b >> 3);
            printf("#%06X 565:0x%04X\n", rgb, rgb565);
        } else if (strcmp(command, "unpack") == 0) {
            unsigned value;
            if (scanf(" #%x", &value) != 1) {
                break;
            }
            printf("%u %u %u\n", (value >> 16) & 0xFFu, (value >> 8) & 0xFFu, value & 0xFFu);
        } else if (strcmp(command, "expand") == 0) {
            unsigned v;
            if (scanf("%x", &v) != 1) {
                break;
            }
            unsigned r = (v >> 11) & 0x1Fu, g = (v >> 5) & 0x3Fu, b = v & 0x1Fu;
            printf("%u %u %u\n", (r << 3) | (r >> 2), (g << 2) | (g >> 4), (b << 3) | (b >> 2));
        }
    }
    return 0;
}

