int main(void) {
    unsigned channels = 0;              // бит K — включён ли канал K
    char command[16];
    while (scanf("%15s", command) == 1) {
        int k;
        if (strcmp(command, "on") == 0 && scanf("%d", &k) == 1 && k >= 0 && k < 32) {
            channels |= 1 << k;
        } else if (strcmp(command, "off") == 0 && scanf("%d", &k) == 1 && k >= 0 && k < 32) {
            channels &= ~(1 << k);
        } else if (strcmp(command, "show") == 0) {
            int count = 0;
            for (int i = 0; i < 32; i++) {
                count += (channels >> i) & 1u;
            }
            printf("%08X, включено: %d\n", channels, count);
        }
    }
    return 0;
}

