#include <stdio.h>
#include <string.h>

static const char ALPHABET[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static void encode(const unsigned char *data, size_t len) {
    for (size_t i = 0; i < len; i += 3) {
        size_t rest = len - i;
        unsigned long v = (unsigned long)data[i] << 16;
        if (rest > 1) {
            v |= (unsigned long)data[i + 1] << 8;
        }
        if (rest > 2) {
            v |= data[i + 2];
        }
        putchar(ALPHABET[(v >> 18) & 63]);
        putchar(ALPHABET[(v >> 12) & 63]);
        putchar(rest > 1 ? ALPHABET[(v >> 6) & 63] : '=');
        putchar(rest > 2 ? ALPHABET[v & 63] : '=');
    }
    putchar('\n');
}

static int value_of(char c) {
    const char *p = c != '\0' ? strchr(ALPHABET, c) : NULL;
    return p != NULL ? (int)(p - ALPHABET) : -1;
}

static int decode(const char *code, size_t len) {
    if (len % 4 != 0) {
        return 0;
    }
    size_t pad = 0;
    while (pad < len && code[len - 1 - pad] == '=') {
        pad++;
    }
    if (pad > 2) {
        return 0;
    }
    for (size_t i = 0; i < len - pad; i++) {
        if (value_of(code[i]) < 0) {
            return 0;
        }
    }
    char out[200];
    size_t n = 0;
    for (size_t i = 0; i < len; i += 4) {
        unsigned long v = 0;
        for (size_t k = 0; k < 4; k++) {
            int part = code[i + k] == '=' ? 0 : value_of(code[i + k]);
            v = v << 6 | (unsigned long)part;
        }
        out[n++] = (char)((v >> 16) & 0xFF);
        out[n++] = (char)((v >> 8) & 0xFF);
        out[n++] = (char)(v & 0xFF);
    }
    n -= pad;
    printf("%.*s\n", (int)n, out);
    return 1;
}

int main(void) {
    char line[256];
    while (fgets(line, sizeof line, stdin) != NULL) {
        size_t len = strcspn(line, "\r\n");
        line[len] = '\0';
        if (len < 1) {
            continue;
        }
        const char *arg = len > 1 ? line + 2 : line + len;
        size_t arg_len = len > 1 ? len - 2 : 0;
        if (line[0] == 'e') {
            encode((const unsigned char *)arg, arg_len);
        } else if (line[0] == 'd' && !decode(arg, arg_len)) {
            printf("ошибка\n");
        }
    }
    return 0;
}

